<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
final class EnrollmentSessionSetup {
 public function __construct(private EnrollmentTransitionAccess $access){}
 public function preview(Request $r,array $d):array{[$sid,$scope]=$this->access->context($r,true);abort_unless($this->access->can($r,'academics.manage'),403);$source=$this->access->row('academic_sessions',$sid,$d['source_session_id']);$target=$this->access->row('academic_sessions',$sid,$d['target_session_id']);if($target->id===$source->id||$target->starts_on<=$source->ends_on||$target->status!=='active')$this->access->fail('Choose a later, non-overlapping active target session.');foreach($d['campus_ids'] as $id){abort_unless(in_array((int)$id,$scope,true),404);if($this->access->row('campuses',$sid,$id)->status!=='active')$this->access->fail('Section setup requires active selected campuses.');}$sourceSections=DB::table('sections')->where('school_id',$sid)->where('academic_session_id',$source->id)->whereIn('campus_id',$d['campus_ids'])->orderBy('id')->get();$rows=[];$snap=[];foreach($sourceSections as $s){$existing=DB::table('sections')->where('school_id',$sid)->where('academic_session_id',$target->id)->where('campus_id',$s->campus_id)->where('class_id',$s->class_id)->where('name',$s->name)->first();$offers=$d['copy_offerings']?DB::table('section_subjects')->where('school_id',$sid)->where('section_id',$s->id)->orderBy('id')->get(['subject_id','required_for_diary']):collect();$rows[]=['source_section_id'=>$s->id,'campus_id'=>$s->campus_id,'class_id'=>$s->class_id,'name'=>$s->name,'capacity'=>$s->capacity,'status'=>$existing?'exists':'create','offering_count'=>$existing?0:$offers->count()];$snap[]=['source'=>get_object_vars($s),'existing'=>$existing,'offerings'=>$offers->all()];}return ['rows'=>$rows,'source_session'=>$source,'target_session'=>$target,'source_digest'=>hash('sha256',json_encode(['source'=>$source,'target'=>$target,'campuses'=>array_map('intval',$d['campus_ids']),'copy_offerings'=>$d['copy_offerings'],'sections'=>$snap])),'note'=>'Existing target sections are left unchanged. Teacher assignments, session terms, enrollments, fee plans and discounts are not copied.'];}
 public function copy(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->access->lock($r);$p=$this->preview($r,$d);if($p['source_digest']!==$d['source_digest'])$this->access->fail('Section structure changed. Preview again before copying.');$ids=[];foreach($p['rows'] as $row){if($row['status']!=='create')continue;$id=DB::table('sections')->insertGetId(['school_id'=>$sid,'campus_id'=>$row['campus_id'],'academic_session_id'=>$d['target_session_id'],'class_id'=>$row['class_id'],'name'=>$row['name'],'capacity'=>$row['capacity'],'created_at'=>now(),'updated_at'=>now()]);if($d['copy_offerings'])foreach(DB::table('section_subjects')->where('school_id',$sid)->where('section_id',$row['source_section_id'])->get() as $offer)DB::table('section_subjects')->insert(['school_id'=>$sid,'section_id'=>$id,'subject_id'=>$offer->subject_id,'required_for_diary'=>$offer->required_for_diary,'created_at'=>now(),'updated_at'=>now()]);$ids[]=$id;}$this->access->audit($r,'section_structure_copied','academic_sessions',$d['target_session_id'],['source_session_id'=>$d['source_session_id'],'created_section_ids'=>$ids,'copy_offerings'=>$d['copy_offerings']]);return ['message'=>count($ids).' target sections created. Existing sections were not changed.','created_ids'=>$ids];});}
}
